for c in changes:
    print(f'{c[0]:20s} {c[1]:8s} {c[2]:50s} {c[3]:10s} -> {c[4]}')

print()
print(f'=== UNCHANGED ({len(unchanged)} entries) ===')
for u in unchanged:
    print(f'{u[0]:20s} {u[1]:8s} {u[2]:50s} {u[3]}')
